def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    if not eight or not markers:
        return out

    # Infer the size of one square tile from contiguous runs of 8s.
    from math import gcd
    runs = []
    for r in range(h):
        n = 0
        for c in range(w):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)
    for c in range(w):
        n = 0
        for r in range(h):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)
    unit = runs[0]
    for n in runs[1:]:
        unit = gcd(unit, n)

    top = min(r for r, c in eight)
    left = min(c for r, c in eight)
    bottom = max(r for r, c in eight)
    right = max(c for r, c in eight)
    nr = (bottom - top + 1) // unit
    nc = (right - left + 1) // unit

    mr0 = min(r for r, c, v in markers)
    mc0 = min(c for r, c, v in markers)
    mr1 = max(r for r, c, v in markers)
    mc1 = max(c for r, c, v in markers)
    mh, mw = mr1 - mr0 + 1, mc1 - mc0 + 1

    # The small colored pattern is rotated clockwise to make the tile pattern.
    pat = [[0] * mw for _ in range(mh)]
    for r, c, v in markers:
        pat[r - mr0][c - mc0] = v
    rotated = [[pat[mh - 1 - c][r] for c in range(mh)]
               for r in range(mw)]

    seeds = [(r, c, rotated[r][c])
             for r in range(len(rotated)) for c in range(len(rotated[0]))
             if rotated[r][c] != 0]

    for tr in range(nr):
        for tc in range(nc):
            r0, c0 = top + tr * unit, left + tc * unit
            if not any(grid[r][c] == 8
                       for r in range(r0, r0 + unit)
                       for c in range(c0, c0 + unit)):
                continue

            color = rotated[tr][tc] if tr < len(rotated) and tc < len(rotated[0]) else 0
            if not color:
                # Extend the nearest pattern color into any extra occupied tile.
                def rank(seed):
                    sr, sc, _ = seed
                    dist = abs(sr - tr) + abs(sc - tc)
                    vertical = 0 if sc == tc else 1
                    return (dist, vertical, sr, sc)
                color = min(seeds, key=rank)[2]

            for r in range(r0, r0 + unit):
                for c in range(c0, c0 + unit):
                    if grid[r][c] == 8:
                        out[r][c] = color
    return out
